import sys

def min_nop_instructions(program):
    instructions = 0
    current_address = 0
    for char in program:
        if char.isupper():
            instructions += 1
            if current_address % 4 != 0:
                current_address += 4 - (current_address % 4)
            current_address += 1
        else:
            current_address += 1
    return (current_address - 1 + 3) // 4 - instructions

